import AppKit

/// Polls the general pasteboard (macOS has no change notification) and hands new content to the store.
final class PasteboardMonitor {
    private let pasteboard = NSPasteboard.general
    private let store: ClipStore
    private var lastChangeCount: Int
    private var timer: Timer?

    /// Markers set by password managers and other apps that ask not to be recorded.
    /// See http://nspasteboard.org
    private static let privateTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
    ]

    init(store: ClipStore) {
        self.store = store
        lastChangeCount = pasteboard.changeCount
    }

    func start() {
        let timer = Timer(timeInterval: 0.4, repeats: true) { [weak self] _ in self?.poll() }
        RunLoop.main.add(timer, forMode: .common)
        self.timer = timer
    }

    /// Call right after Clipline itself wrote to the pasteboard so it isn't recorded twice.
    func skipCurrentChange() {
        lastChangeCount = pasteboard.changeCount
    }

    private func poll() {
        let count = pasteboard.changeCount
        guard count != lastChangeCount else { return }
        lastChangeCount = count

        guard !Prefs.paused, let types = pasteboard.types, !types.isEmpty else { return }
        if types.contains(where: { Self.privateTypes.contains($0.rawValue) }) { return }

        let app = NSWorkspace.shared.frontmostApplication
        if let id = app?.bundleIdentifier, Prefs.ignoredApps.contains(id) { return }
        capture(types: types, appName: app?.localizedName, bundleID: app?.bundleIdentifier)
    }

    private func capture(types: [NSPasteboard.PasteboardType], appName: String?, bundleID: String?) {
        if types.contains(.fileURL),
           let urls = pasteboard.readObjects(forClasses: [NSURL.self],
                                             options: [.urlReadingFileURLsOnly: true]) as? [URL],
           !urls.isEmpty {
            store.ingestFiles(urls, appName: appName, bundleID: bundleID)
            return
        }

        // Apps put their richest representation first. Treat it as an image when an image type
        // comes before plain text (e.g. "Copy Image" in a browser), otherwise prefer the text.
        let imageIndex = types.firstIndex { $0 == .png || $0 == .tiff }
        let stringIndex = types.firstIndex(of: .string)
        if let imageIndex, stringIndex.map({ imageIndex < $0 }) ?? true,
           let data = pasteboard.data(forType: types[imageIndex]) {
            store.ingestImage(data, kind: .image, appName: appName, bundleID: bundleID)
            return
        }

        if let string = pasteboard.string(forType: .string),
           !string.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            store.ingestText(string, appName: appName, bundleID: bundleID)
        }
    }
}
